function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*49999+47);var domains=['materials-science','logistics','music-theory','agronomy','topology'];var d=domains[(R()*domains.length)|0];var parts={model:'llm-'+(7+((R()*60)|0))+'b',tools:['search','code-exec','chart'],datasets:['domain-corpus-v1'],eval:['gold-set-200']};if(R()<0.15){parts.model=null;}var need=['model','tools','datasets','eval'];var have=need.filter(function(k){return parts[k]&&(Array.isArray(parts[k])?parts[k].length:true);});return{domain:d,config:parts,completeness_pct:+(have.length/need.length*100).toFixed(0),ready:have.length===need.length};}
var SEED = 91001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

